{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Launch configuration root volume is not explicitly encrypted",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not enable encryption for its root EBS volume, so instances may store data on unencrypted storage."
    },
    {
      "check_id": "CKV_AWS_389",
      "title": "Public IP assignment is not explicitly disabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly disable public IP assignment, allowing instance exposure to depend on subnet defaults."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "IMDSv2 token enforcement is not enabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "HIGH",
      "explanation": "The launch configuration does not require metadata service tokens, allowing instances to use the less secure IMDSv1 protocol."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix                = \"levelup-launchconfig\"\n  image_id                   = lookup(var.AMIS, var.AWS_REGION)\n  instance_type              = \"t2.micro\"\n  key_name                   = aws_key_pair.levelup_key.key_name\n  associate_public_ip_address = false\n\n  root_block_device {\n    encrypted = true\n  }\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}\n",
  "fix_summary": "Enabled root EBS encryption, explicitly disabled public IP assignment, and enforced IMDSv2 tokens for instances created from the launch configuration."
}
